modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit;
end Baseline;
model FINDING00800
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(T2=0);
end FINDING00800;
model FINDING00801
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(T1=0);
end FINDING00801;
model FINDING00785
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(PIA(R1=0));
end FINDING00785;
model FINDING00790
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(firstOrder1A(R2=0));
end FINDING00790;
model FINDING00797
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(firstOrder2A(R2=0));
end FINDING00797;
model FinalFINDING00800
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(final T2=0);
end FinalFINDING00800;
model FinalFINDING00801
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(final T1=0);
end FinalFINDING00801;
model FinalFINDING00785
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(PIA(final R1=0));
end FinalFINDING00785;
model FinalFINDING00790
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(firstOrder1A(final R2=0));
end FinalFINDING00790;
model FinalFINDING00797
  extends Modelica.Electrical.Analog.Examples.OpAmps.ControlCircuit(firstOrder2A(final R2=0));
end FinalFINDING00797;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00800\n");
simulate(FINDING00800, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00801\n");
simulate(FINDING00801, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00785\n");
simulate(FINDING00785, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00790\n");
simulate(FINDING00790, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00797\n");
simulate(FINDING00797, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00800\n");
simulate(FinalFINDING00800, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00801\n");
simulate(FinalFINDING00801, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00785\n");
simulate(FinalFINDING00785, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00790\n");
simulate(FinalFINDING00790, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00797\n");
simulate(FinalFINDING00797, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00800\n");
system("./Baseline -override T2=0 -r=FINDING00800_override.csv");
print("AUDIT_OVERRIDE FINDING00801\n");
system("./Baseline -override T1=0 -r=FINDING00801_override.csv");
print("AUDIT_OVERRIDE FINDING00785\n");
system("./Baseline -override PIA.R1=0 -r=FINDING00785_override.csv");
print("AUDIT_OVERRIDE FINDING00790\n");
system("./Baseline -override firstOrder1A.R2=0 -r=FINDING00790_override.csv");
print("AUDIT_OVERRIDE FINDING00797\n");
system("./Baseline -override firstOrder2A.R2=0 -r=FINDING00797_override.csv");
